-- Clearo demo seed data
-- Run this whole file manually against the demo Neon branch after migrations.
--
-- Demo credentials:
--   Patient:      patient.demo@clearo.test / DemoPatient123! / OTP 000000
--   Clinic admin: clinic.admin@clearo.test / DemoClinic123!
--   Clinic staff: clinic.staff@clearo.test / DemoStaff123!
--
-- The clinic admin owns all seeded clinics.
-- Only Northside Imaging Melbourne has public bookable slots.

BEGIN;

DELETE FROM public.auth_accounts WHERE "userId" IN (SELECT id FROM public.auth_users WHERE lower(email) = 'patient.demo@clearo.test');
DELETE FROM public.auth_sessions WHERE "userId" IN (SELECT id FROM public.auth_users WHERE lower(email) = 'patient.demo@clearo.test');
DELETE FROM public.audit_logs WHERE user_id IN (SELECT id FROM public.auth_users WHERE lower(email) = 'patient.demo@clearo.test');
DELETE FROM public.patient_profiles WHERE user_id IN (SELECT id FROM public.auth_users WHERE lower(email) = 'patient.demo@clearo.test');
DELETE FROM public.auth_users WHERE lower(email) = 'patient.demo@clearo.test';
DELETE FROM clinic.users WHERE normalized_email IN ('clinic.admin@clearo.test', 'clinic.staff@clearo.test');
DELETE FROM public.clinics WHERE lower(email) IN ('northside.demo@clearo.test', 'yarra.demo@clearo.test', 'bayview.demo@clearo.test', 'harbour.demo@clearo.test', 'innerwest.demo@clearo.test', 'parramatta.demo@clearo.test');

INSERT INTO public.scan_types (name, description, icon, requires_referral, prep_instructions, safety_question_set) SELECT 'MRI', 'Magnetic resonance imaging for soft tissue and neurological scans.', 'magnet', true, 'Bring your referral and remove metal objects before the appointment.', '[{"id":"implants","question":"Do you have any implanted devices?","action":"require_approval"},{"id":"pregnancy","question":"Are you pregnant or possibly pregnant?","action":"require_approval"}]'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.scan_types WHERE lower(name) = 'mri');
INSERT INTO public.scan_types (name, description, icon, requires_referral, prep_instructions, safety_question_set) SELECT 'CT Scan', 'Cross-sectional imaging for diagnostic assessment.', 'scan', true, 'Bring your referral. Fasting may be required for contrast studies.', '[{"id":"contrast","question":"Have you previously reacted to contrast?","action":"require_approval"}]'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.scan_types WHERE lower(name) = 'ct scan');
INSERT INTO public.scan_types (name, description, icon, requires_referral, prep_instructions, safety_question_set) SELECT 'X-Ray', 'Common imaging for bones, chest, and joint assessment.', 'bone', true, 'Bring your referral and any previous imaging if available.', '[]'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.scan_types WHERE lower(name) = 'x-ray');
INSERT INTO public.scan_types (name, description, icon, requires_referral, prep_instructions, safety_question_set) SELECT 'Ultrasound', 'Sound wave imaging for soft tissue, abdominal, and pregnancy scans.', 'waves', true, 'Some scans require water intake or fasting. Check clinic instructions.', '[]'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.scan_types WHERE lower(name) = 'ultrasound');

UPDATE public.scan_types SET description = 'Magnetic resonance imaging for soft tissue and neurological scans.', icon = 'magnet', requires_referral = true, prep_instructions = 'Bring your referral and remove metal objects before the appointment.', safety_question_set = '[{"id":"implants","question":"Do you have any implanted devices?","action":"require_approval"},{"id":"pregnancy","question":"Are you pregnant or possibly pregnant?","action":"require_approval"}]'::jsonb WHERE lower(name) = 'mri';
UPDATE public.scan_types SET description = 'Cross-sectional imaging for diagnostic assessment.', icon = 'scan', requires_referral = true, prep_instructions = 'Bring your referral. Fasting may be required for contrast studies.', safety_question_set = '[{"id":"contrast","question":"Have you previously reacted to contrast?","action":"require_approval"}]'::jsonb WHERE lower(name) = 'ct scan';
UPDATE public.scan_types SET description = 'Common imaging for bones, chest, and joint assessment.', icon = 'bone', requires_referral = true, prep_instructions = 'Bring your referral and any previous imaging if available.', safety_question_set = '[]'::jsonb WHERE lower(name) = 'x-ray';
UPDATE public.scan_types SET description = 'Sound wave imaging for soft tissue, abdominal, and pregnancy scans.', icon = 'waves', requires_referral = true, prep_instructions = 'Some scans require water intake or fasting. Check clinic instructions.', safety_question_set = '[]'::jsonb WHERE lower(name) = 'ultrasound';

INSERT INTO public.auth_users (name, email, "emailVerified", role) VALUES ('Avery Demo', 'patient.demo@clearo.test', NOW(), 'patient');
INSERT INTO public.auth_accounts ("userId", provider, type, "providerAccountId", password) SELECT id, 'credentials', 'credentials', id::text, '$2a$12$V76p2kFKfGawezaaAV7aYuYS/YlnFVEAcr8uolU/fjZ1Tn31y8DHm' FROM public.auth_users WHERE lower(email) = 'patient.demo@clearo.test';

INSERT INTO clinic.users (email, normalized_email, name, password_hash, email_verified_at, status) VALUES ('clinic.admin@clearo.test', 'clinic.admin@clearo.test', 'Dr Morgan Admin', '$2a$12$7exH/u4gEkVZldoWwYGfTeRTNb8SNeaukNAlBYPWX40qHqr7OH8g.', NOW(), 'active');
INSERT INTO clinic.users (email, normalized_email, name, password_hash, email_verified_at, status) VALUES ('clinic.staff@clearo.test', 'clinic.staff@clearo.test', 'Taylor Staff', '$2a$12$f9DGGqFQano/JJ.a6rfnkORQXUxAEDiubuzuNi/Y5yCYN11MXMTa6', NOW(), 'active');

