INSERT INTO clinic.memberships (clinic_id, clinic_user_id, role, status, accepted_at) SELECT c.id, cu.id, 'owner', 'active', NOW() FROM public.clinics c CROSS JOIN clinic.users cu WHERE lower(c.email) IN ('northside.demo@clearo.test', 'yarra.demo@clearo.test', 'bayview.demo@clearo.test', 'harbour.demo@clearo.test', 'innerwest.demo@clearo.test', 'parramatta.demo@clearo.test') AND cu.normalized_email = 'clinic.admin@clearo.test';
INSERT INTO clinic.memberships (clinic_id, clinic_user_id, role, status, accepted_at) SELECT c.id, cu.id, 'staff', 'active', NOW() FROM public.clinics c CROSS JOIN clinic.users cu WHERE lower(c.email) = 'northside.demo@clearo.test' AND cu.normalized_email = 'clinic.staff@clearo.test';

INSERT INTO public.clinic_hours (clinic_id, day_of_week, open_time, close_time, is_closed) SELECT c.id, day_number, '08:30'::time, '17:00'::time, false FROM public.clinics c CROSS JOIN generate_series(1, 5) AS days(day_number) WHERE lower(c.email) IN ('northside.demo@clearo.test', 'yarra.demo@clearo.test', 'bayview.demo@clearo.test', 'harbour.demo@clearo.test', 'innerwest.demo@clearo.test', 'parramatta.demo@clearo.test');

INSERT INTO public.clinic_scans (clinic_id, scan_type_id, price, duration_minutes, available, requires_referral, prep_instructions) SELECT c.id, st.id, p.price, 30, true, true, 'Bring your referral and any previous imaging if available.' FROM public.clinics c JOIN (VALUES ('northside.demo@clearo.test','MRI',520),('northside.demo@clearo.test','CT Scan',360),('northside.demo@clearo.test','X-Ray',95),('northside.demo@clearo.test','Ultrasound',180),('yarra.demo@clearo.test','MRI',560),('yarra.demo@clearo.test','CT Scan',390),('yarra.demo@clearo.test','X-Ray',110),('yarra.demo@clearo.test','Ultrasound',205),('bayview.demo@clearo.test','MRI',610),('bayview.demo@clearo.test','CT Scan',420),('bayview.demo@clearo.test','X-Ray',125),('bayview.demo@clearo.test','Ultrasound',225),('harbour.demo@clearo.test','MRI',540),('harbour.demo@clearo.test','CT Scan',370),('harbour.demo@clearo.test','X-Ray',105),('harbour.demo@clearo.test','Ultrasound',190),('innerwest.demo@clearo.test','MRI',575),('innerwest.demo@clearo.test','CT Scan',405),('innerwest.demo@clearo.test','X-Ray',115),('innerwest.demo@clearo.test','Ultrasound',215),('parramatta.demo@clearo.test','MRI',595),('parramatta.demo@clearo.test','CT Scan',415),('parramatta.demo@clearo.test','X-Ray',120),('parramatta.demo@clearo.test','Ultrasound',220)) AS p(clinic_email, scan_name, price) ON lower(c.email) = p.clinic_email JOIN public.scan_types st ON lower(st.name) = lower(p.scan_name);

INSERT INTO public.machines (clinic_id, scan_type_id, machine_name, manufacturer, model, is_active) SELECT c.id, st.id, st.name || ' Room', 'DemoMed', 'DX-100', true FROM public.clinics c CROSS JOIN public.scan_types st WHERE lower(c.email) IN ('northside.demo@clearo.test', 'yarra.demo@clearo.test', 'bayview.demo@clearo.test', 'harbour.demo@clearo.test', 'innerwest.demo@clearo.test', 'parramatta.demo@clearo.test') AND lower(st.name) IN ('mri', 'ct scan', 'x-ray', 'ultrasound');

INSERT INTO public.available_slots (clinic_id, machine_id, slot_date, slot_time, duration_minutes, is_available) SELECT m.clinic_id, m.id, slot_day::date, slot_time::time, 30, true FROM public.machines m JOIN public.clinics c ON c.id = m.clinic_id CROSS JOIN generate_series(CURRENT_DATE + INTERVAL '1 day', CURRENT_DATE + INTERVAL '21 days', INTERVAL '1 day') AS days(slot_day) CROSS JOIN (VALUES ('09:00'), ('11:00'), ('14:00')) AS times(slot_time) WHERE lower(c.email) = 'northside.demo@clearo.test' AND EXTRACT(ISODOW FROM slot_day) BETWEEN 1 AND 5 ON CONFLICT DO NOTHING;

COMMIT;

SELECT 'public.clinics' AS table_name, COUNT(*)::int AS demo_rows FROM public.clinics WHERE lower(email) IN ('northside.demo@clearo.test', 'yarra.demo@clearo.test', 'bayview.demo@clearo.test', 'harbour.demo@clearo.test', 'innerwest.demo@clearo.test', 'parramatta.demo@clearo.test')
UNION ALL SELECT 'public.auth_users', COUNT(*)::int FROM public.auth_users WHERE lower(email) = 'patient.demo@clearo.test'
UNION ALL SELECT 'clinic.users', COUNT(*)::int FROM clinic.users WHERE normalized_email IN ('clinic.admin@clearo.test', 'clinic.staff@clearo.test')
UNION ALL SELECT 'clinic.memberships', COUNT(*)::int FROM clinic.memberships cm JOIN clinic.users cu ON cu.id = cm.clinic_user_id WHERE cu.normalized_email IN ('clinic.admin@clearo.test', 'clinic.staff@clearo.test')
UNION ALL SELECT 'public.clinic_scans', COUNT(*)::int FROM public.clinic_scans cs JOIN public.clinics c ON c.id = cs.clinic_id WHERE lower(c.email) IN ('northside.demo@clearo.test', 'yarra.demo@clearo.test', 'bayview.demo@clearo.test', 'harbour.demo@clearo.test', 'innerwest.demo@clearo.test', 'parramatta.demo@clearo.test')
UNION ALL SELECT 'public.machines', COUNT(*)::int FROM public.machines m JOIN public.clinics c ON c.id = m.clinic_id WHERE lower(c.email) IN ('northside.demo@clearo.test', 'yarra.demo@clearo.test', 'bayview.demo@clearo.test', 'harbour.demo@clearo.test', 'innerwest.demo@clearo.test', 'parramatta.demo@clearo.test')
UNION ALL SELECT 'public.available_slots', COUNT(*)::int FROM public.available_slots s JOIN public.clinics c ON c.id = s.clinic_id WHERE lower(c.email) = 'northside.demo@clearo.test';
